import numpy as np

def obs(agent=(5,5), objects=(), prev=None):
    a = np.zeros((10, 10, 5), dtype=np.float32)
    # wall border in obstacle channel
    a[0, :, 3] = 1
    a[9, :, 3] = 1
    a[:, 0, 3] = 1
    a[:, 9, 3] = 1

    if agent is not None:
        a[agent[0], agent[1], 0] = 1

    for (r, c, ch) in objects:
        a[r, c, ch] = 1

    # previous frame: by default just the current agent position
    if prev is None:
        if agent is not None:
            a[agent[0], agent[1], 4] = 1
    else:
        for (r, c) in prev:
            a[r, c, 4] = 1

    return a.reshape(-1)

X = []
meta = []

def add(label, **kw):
    X.append(obs(**kw))
    meta.append(label)

# baseline: agent at center, empty playable area
