        row += sym[int(np.argmax(probs[idx]))]
    print(row)
print("mean agent probs [N,U,D,L,R]:", np.round(probs[start_agent:start_agent + 64].mean(axis=0), 3))

# perturbation effects
idx = 1
for ch in [1, 2, 3]:
