import numpy as np

def base(agent=None, extras=()):
    x = np.zeros(500, dtype=np.float64)
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                x[(r*10+c)*5+3] = 1.0          # wall border (obstacles)
    if agent is not None:
        r,c = agent
        x[(r*10+c)*5+0] = 1.0              # agent
    for (r,c,ch) in extras:
        x[(r*10+c)*5+ch] = 1.0
    return x

def probs(z):
    e = np.exp(z - z.max()); return e / e.sum()

