inputs.append(np.zeros(500)); tags.append(("allzero",))
inputs.append(np.ones(500));  tags.append(("allone",))
inputs.append(base(None));    tags.append(("border_only",))
rng=np.random.RandomState(0)
inputs.append(rng.rand(500)); tags.append(("random",))
for r in range(1,9):
    for c in range(1,9):
        inputs.append(base((r,c))); tags.append(("agent",r,c))

out1=np.asarray(forward(np.array(inputs)))
